namespace QuantForge.Core;public sealed record ProgramReadinessReport(string AppVersion,string BuildCode,bool EngineeringCandidate,bool NativeValidated,bool DeviceValidated,bool StableEligible,bool SimulationOnly,bool LiveAuthorityEnabled,IReadOnlyList<string> BlockingGates);public static class ProgramReadinessReportRules{public static ProgramReadinessReport Create(ReleaseCandidateSummary release,ProductResearchWorkspaceDashboard workspace){var blockers=new List<string>();blockers.AddRange(release.Missing);if(!workspace.Consistent)blockers.Add("workspace-consistency");if(workspace.Gates==0)blockers.Add("research-gates");var native=release.AndroidNativeValidated&&release.WindowsNativeValidated;var device=release.AndroidDeviceAccepted&&release.WindowsAccepted;return new(release.AppVersion,release.BuildCode,workspace.Consistent&&workspace.Gates>0,native,device,release.StableEligible&&workspace.Consistent&&workspace.Gates>0,true,false,blockers.Distinct(StringComparer.Ordinal).OrderBy(x=>x,StringComparer.Ordinal).ToArray());}}
